// Paperless-Workflow sendet {"doc_url": ".../documents/123/"} oder {"document_id": 123}.
// ToyPost braucht nur die ID; den Text holt ToyPost selbst aus Paperless.
const crypto = require('crypto');
const body = $input.first().json.body ?? $input.first().json;
let id = Number(body.document_id ?? body.id);
if (!id && body.doc_url) {
  const m = String(body.doc_url).match(/documents\/(\d+)/);
  if (m) id = Number(m[1]);
}
if (!id) throw new Error('Keine Paperless-Dokument-ID im Webhook gefunden.');

const payload = JSON.stringify({ documentId: id, channel: body.source === 'mail' ? 'mail' : 'scan' });
// Geheimnis aus ToyPost: Konto → Verbindungen (oder GET /v1/integrations/webhook-secret)
const secret = $env.TOYPOST_WEBHOOK_SECRET;
if (!secret) throw new Error('Umgebungsvariable TOYPOST_WEBHOOK_SECRET fehlt.');
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');
return [{ json: { payload, signature } }];
